package com.example.campsitelottery

/**
 * [RatingRepository] that keeps ratings in memory. Callbacks run synchronously.
 *
 * @param campsites campsites that can be rated, keyed by their IDs.
 */
class InMemoryRatingRepository(campsites: List<Campsite> = emptyList()) : RatingRepository {

    private val owners = campsites.associate { it.campsiteId to it.ownerId }.toMutableMap()
    private val totals = campsites.associate { it.campsiteId to RatingPolicy.totalsOf(it) }.toMutableMap()
    private val ratings = mutableMapOf<Pair<String, String>, Int>()

    /** When set, every operation fails with this exception instead of running. */
    var failWith: Exception? = null

    /** Returns the stored totals for [campsiteId], or null if the campsite is unknown. */
    fun totalsFor(campsiteId: String): RatingPolicy.Totals? = totals[campsiteId]

    override fun getMyRating(
        campsiteId: String,
        userId: String,
        onSuccess: (Int?) -> Unit,
        onFailure: (Exception) -> Unit,
    ) {
        failWith?.let { return onFailure(it) }
        onSuccess(ratings[campsiteId to userId])
    }

    override fun submitRating(
        campsiteId: String,
        userId: String,
        stars: Int,
        onSuccess: (RatingPolicy.Totals) -> Unit,
        onFailure: (Exception) -> Unit,
    ) {
        failWith?.let { return onFailure(it) }
        val ownerId = owners[campsiteId]
            ?: return onFailure(IllegalStateException("This campsite no longer exists."))
        if (!RatingPolicy.canRate(ownerId, userId)) {
            return onFailure(IllegalStateException("You can't rate your own campsite."))
        }
        val updated = try {
            RatingPolicy.apply(totals.getValue(campsiteId), ratings[campsiteId to userId], stars)
        } catch (e: IllegalArgumentException) {
            return onFailure(e)
        }
        ratings[campsiteId to userId] = stars
        totals[campsiteId] = updated
        onSuccess(updated)
    }
}
